package ru.fifth.horror.client.gui;
import net.fabricmc.fabric.api.client.networking.v1.ClientPlayNetworking;import net.fabricmc.fabric.api.networking.v1.PacketByteBufs;import net.minecraft.client.gui.DrawContext;import net.minecraft.client.gui.screen.Screen;import net.minecraft.network.PacketByteBuf;import net.minecraft.text.Text;import ru.fifth.horror.entity.MonsterForLiftEntity;import ru.fifth.horror.network.FifthNetworking;
public final class MflEditorScreen extends HorrorScreen{private final Screen parent;private final int id;private String status="";public MflEditorScreen(Screen p,MonsterForLiftEntity m){super(Text.literal("FIVEN / MFL EDITOR"));parent=p;id=m.getId();}@Override protected void init(){beginHorrorInit();int w=contentWidth(430),x=(width-w)/2,y=safeTop(),bh=22,g=6;addDrawableChild(HorrorButton.builder(Text.literal("▶ / ■ Маршрут MFL"),b->send("toggle_route")).dimensions(x,y,w,bh).build());addDrawableChild(HorrorButton.builder(Text.literal("Очистить маршрут"),b->send("clear_route")).dimensions(x,y+28,w,bh).build());addDrawableChild(HorrorButton.builder(Text.literal("Анимация: посмотреть влево"),b->anim("looking_left")).dimensions(x,y+56,w,bh).build());addDrawableChild(HorrorButton.builder(Text.literal("Анимация: посмотреть вправо"),b->anim("looking_right")).dimensions(x,y+84,w,bh).build());addDrawableChild(HorrorButton.builder(Text.literal("Анимация: посмотреть назад"),b->anim("looking_backward")).dimensions(x,y+112,w,bh).build());addDrawableChild(HorrorButton.builder(Text.literal("Назад"),b->client.setScreen(parent)).dimensions(x,y+146,w,bh).build());}private void send(String a){PacketByteBuf b=PacketByteBufs.create();b.writeVarInt(id);b.writeString(a,64);ClientPlayNetworking.send(FifthNetworking.MFL_CONTROL,b);status="Команда MFL: "+a;}private void anim(String a){PacketByteBuf b=PacketByteBufs.create();b.writeVarInt(id);b.writeString("animation",64);b.writeString(a,128);ClientPlayNetworking.send(FifthNetworking.MFL_CONTROL,b);status="Проигрывается: "+a;}@Override public void render(DrawContext c,int mx,int my,float d){horrorBackground(c);if(!status.isBlank())c.drawCenteredTextWithShadow(textRenderer,status,width/2,height-safeBottom()-15,0xFFD89090);super.render(c,mx,my,d);}}
